import logging
import traceback
import uuid

logger = logging.getLogger(__name__)


class OrderService:
    def __init__(self, stock) -> None:
        """`stock` is a client for the remote inventory service. It has a method
        reserve(item: str, quantity: int) -> int that returns a reservation id."""
        self.stock = stock

    def place_order(
        self, user: str, item: str, quantity: int, is_admin: bool = False
    ) -> tuple[int, str]:
        """Handle an order request from the web page.
        Returns (HTTP status code, text shown to the user); on success (200, a confirmation text)."""
        try:
            reservation_id = self.stock.reserve(item, quantity)
            return (
                200,
                f"Order placed successfully for user '{user}'. Reservation ID: {reservation_id}.",
            )
        except Exception as exc:
            error_id = str(uuid.uuid4())
            logger.error(
                "Unexpected error processing order [Reference Code: %s]: %s",
                error_id,
                exc,
                exc_info=True,
            )

            if is_admin:
                tb_str = traceback.format_exc()
                message = (
                    f"An error occurred (Reference Code: {error_id}).\n"
                    f"Exception: {type(exc).__name__}: {exc}\nTraceback:\n{tb_str}"
                )
            else:
                message = (
                    "An unexpected error occurred while processing your order. "
                    f"Please contact support with reference code: {error_id}."
                )

            return 500, message
```

